const hasCurrentPurposeVersion = (
  purpose: Option.Option<ProcessingPurpose>,
  purposeVersionId: string,
  evaluatedAt: string,
): boolean => {
  if (Option.isNone(purpose)) {
    return false;
  }
  const versions = purpose.value.versions.filter(
    (version) =>
      isPrivacyInstantAtOrBefore(version.effectiveFrom, evaluatedAt) &&
      (version.effectiveTo === null || isPrivacyInstantAfter(version.effectiveTo, evaluatedAt)),
  );
  const [version] = versions;
  return versions.length === 1 && purpose.value.lifecycle === 'ACTIVE' && version?.versionId === purposeVersionId;
};

/** Exact subject and use are resolved from current owner configuration, never request metadata. */
export const evaluateSourceProcessingEligibility = Effect.fn('Privacy.evaluateSourceProcessingEligibility')(
  function* evaluateSource(
    request: SourceProcessingEligibilityRequest,
    scope: OperationalScope,
    services: SourceProcessingEligibilityServices,
    evaluatedAt: string,
  ): Effect.fn.Return<SourceProcessingEligibilityResponse, ReadHandlerUnavailable> {
    const { sourceSync } = services;
    if (sourceSync !== undefined && sourceSyncProcessingPolicyMatches(sourceSync.policy, request, scope)) {
      return yield* evaluateSourceSync(request, sourceSync, evaluatedAt);
    }
    const communications = request.consumerModuleId === CommunicationsSourceProcessingConsumerModule;
    // Only the Communications consumer is told WHY nothing was evaluated; every other consumer keeps its exact response.
    const denied = (
      reason: 'AUTHORITY_NOT_CURRENT' | 'PROCESSING_NOT_ALLOWED' | 'PROTECTED_MATERIAL',
      notEvaluated?: SourceProcessingNotEvaluatedCause,
    ) => {
      const response = { evaluatedAt, outcome: 'DENIED' as const, reason };
      return communications && notEvaluated !== undefined
        ? { ...response, eligibility: { outcome: 'NOT_EVALUATED' as const, reasonCode: notEvaluated } }
        : response;
    };
    const exactContexts = services.contexts.filter(
      (context) =>
        sourceRequestMatches(context, request) &&
        context.tenantId === scope.tenantId &&
        context.legalEntityId === scope.legalEntityId &&
        contextCallerMatches(context, request, scope),
    );
    const [context] = exactContexts;
    if (context === undefined) {
      return denied('AUTHORITY_NOT_CURRENT', 'NO_CONTEXT');
    }
    if (exactContexts.length !== 1) {
      return denied('AUTHORITY_NOT_CURRENT', 'MULTIPLE_CONTEXTS');
    }
    if (scope.legalEntityId === undefined || !currentContextMatches(context, request, scope, evaluatedAt)) {
      return denied('AUTHORITY_NOT_CURRENT', 'CONTEXT_NOT_CURRENT');
    }
    const { applicabilityAuthority, intendedScope } = context;
    const authority = { ...applicabilityAuthority, asOf: evaluatedAt };
    const [history, policies, purpose, protections] = yield* Effect.all(
      [
        services.repository.listApplicabilityDecisions(scope.tenantId, scope.legalEntityId),
        services.repository.listApplicabilityPolicies(scope.tenantId, scope.legalEntityId),
        services.purposes.get(scope.tenantId, scope.legalEntityId, intendedScope.purposeRef),
        services.protections(intendedScope.subjectRef.resourceId, request),
      ],
      { concurrency: 4 },
    ).pipe(Effect.mapError(unavailable));
    if (!hasCurrentPurposeVersion(purpose, intendedScope.purposeVersionId, evaluatedAt)) {
      return denied('PROCESSING_NOT_ALLOWED', 'PURPOSE_NOT_CURRENT');
    }
    const latest = latestPrivacyApplicabilityDecisionsForExactAuthorities(history, authority.scope, evaluatedAt).filter(
      (decision) => decision.authority !== undefined && authorityEquivalent(decision.authority, authority.authority),
    );
    const [decision] = latest;
    if (
      latest.length !== 1 ||
      decision === undefined ||
      decision.evaluatedAt !== authority.decisionEvaluatedAt ||
      decision.outcome !== 'APPLICABLE'
    ) {
      return denied('AUTHORITY_NOT_CURRENT', 'APPLICABILITY_NOT_CURRENT');
    }
    const reevaluated = resolvePrivacyApplicability({
      authority: authority.authority,
      authorityEvidenceRefs: authority.evidenceRefs,
      authorityReceiptRef: authority.receiptRef,
      evaluatedAt,
      policies,
      proposedActivity: decision.proposedActivity,
      responsibilityAssignmentRefs: decision.responsibilityAssignmentRefs,
      scope: authority.scope,
    });
    if (!privacyApplicabilityDecisionsAreEquivalent({ ...reevaluated, evaluatedAt: decision.evaluatedAt }, decision)) {
      return denied('AUTHORITY_NOT_CURRENT', 'APPLICABILITY_NOT_CURRENT');
    }
    const protectedSubjects = new Set([
      intendedScope.subjectRef.resourceId,
      ...protections.items.map((item) => item.subjectRef),
    ]);
    const sourceProtectionSubjects = new Set(protections.sourceSubjectRefs);
    const exactResourceRefs =
      request.target === null ? context.resourceRefs : [...context.resourceRefs, request.target.resourceId];
    const protectedMaterial = [...protectedSubjects].some((subjectRef) => {
      const resourceRefs = sourceProtectionSubjects.has(subjectRef)
        ? [
            ...exactResourceRefs,
            ...protections.items.flatMap((item) => (item.subjectRef === subjectRef ? item.resourceRefs : [])),
          ]
        : exactResourceRefs;
      const contentScopeRefs = sourceProtectionSubjects.has(subjectRef)
        ? [
            ...context.contentScopeRefs,
            ...protections.items.flatMap((item) => (item.subjectRef === subjectRef ? item.contentScopeRefs : [])),
          ]
        : context.contentScopeRefs;
      return (
        assessAntiResurrection(protections.items, {
          contentScopeRefs,
          operation: 'REPLAY',
          resourceRefs,
          sourceInputIsNew: false,
          sourceInputRef: null,
          subjectRef,
          tenantId: scope.tenantId,
        }).decision !== 'ALLOW'
      );
    });
    if (protectedMaterial) {
      return denySourceProcessing(evaluatedAt, 'PROTECTED_MATERIAL');
    }
    // A known protection also blocks Party's original-source evidence read. Apply it before requesting that proof.
    if (!(yield* services.subjectExists(intendedScope.subjectRef.resourceId, request, context.targetAdmission))) {
      return denied('AUTHORITY_NOT_CURRENT', 'SUBJECT_NOT_FOUND');
    }
    const resolved = yield* services.repository
      .resolveEligibilityInputs(scope.tenantId, scope.legalEntityId, intendedScope, evaluatedAt, authority)
      .pipe(Effect.mapError(unavailable));
    const outcome = evaluatePrivacyEligibility(resolved.input);
    if (outcome.outcome !== 'ALLOWED') {
      // Both non-allowed outcomes stop the processing and stay DENIED/PROCESSING_NOT_ALLOWED. Only the Communications
      // consumer additionally receives which one it was, with the owner's own evidence, so a proven prohibition is never
      // confused with an input the owner could not evidence. Every other consumer keeps its existing response.
      return communications
        ? {
            ...denied('PROCESSING_NOT_ALLOWED'),
            eligibility: {
              evidence: createPrivacyEligibilityEvidence({
                authoritativeReferences: resolved.authoritativeReferences,
                outcome,
                policyRevisions: resolved.policyRevisions,
              }),
              outcome: outcome.outcome,
            },
          }
        : denied('PROCESSING_NOT_ALLOWED');
    }
    return {
      authorityIncarnation: context.authorityIncarnation,
      authorityRevision: context.authorityRevision,
      evaluatedAt,
      evidence: createPrivacyEligibilityEvidence({
        authoritativeReferences: resolved.authoritativeReferences,
        outcome,
        policyRevisions: resolved.policyRevisions,
      }),
      outcome: 'ALLOWED',
    };
  },
);

type SourceTransaction = Parameters<ReadServiceFactory<Readonly<Record<string, never>>>>[0];

const sourceLinkedDataSubjectRefs = Effect.fn('Privacy.sourceLinkedDataSubjectRefs')(function* linkedSubjects(
  transaction: SourceTransaction,
  scope: OperationalScope,
  bound: PrivacySubjectRecord,
  request: SourceProcessingEligibilityRequest,
  anchors: readonly string[],
) {
  if (
    anchors.length === 0 ||
    (bound.subject.kind !== 'SOURCE_ASSERTED' && request.source === null && request.partySourceReference === undefined)
  ) {
    return [];
  }
  const sourceAnchors = new Set(anchors);
  const admitted = yield* transaction
    .select({ record: privacySubjects.subjectRecord, subjectId: privacySubjects.privacySubjectId })
    .from(privacySubjects)
    .where(
      and(
        eq(privacySubjects.tenantId, scope.tenantId),
        eq(privacySubjects.legalEntityId, scope.legalEntityId ?? ''),
        eq(privacySubjects.subjectKind, 'DATA_SUBJECT'),
        inArray(
          sql<string>`${privacySubjects.subjectRecord}->'subject'->'sourceAdmission'->'sourceSubjectRef'->>'resourceId'`,
          [...sourceAnchors],
        ),
      ),
    )
    .pipe(Effect.mapError(unavailable));
  return yield* Effect.forEach(
    admitted,
    Effect.fn('Privacy.sourceLinkedDataSubjectRefs.validate')(function* validate(row) {
      const record = yield* Schema.decodeUnknownEffect(PrivacySubjectRecordSchema)(row.record).pipe(
        Effect.mapError(unavailable),
      );
      if (
        record.subject.kind !== 'DATA_SUBJECT' ||
        record.subjectRef.tenantId !== scope.tenantId ||
        record.subjectRef.resourceId !== row.subjectId ||
        record.subject.sourceAdmission === undefined ||
        record.subject.sourceAdmission.sourceSubjectRef.tenantId !== scope.tenantId ||
        !sourceAnchors.has(record.subject.sourceAdmission.sourceSubjectRef.resourceId)
      ) {
        return yield* unavailable();
      }
      return record.subjectRef.resourceId;
    }),
    { concurrency: 1 },
  );
});

